using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Tools -------------------------------------------------------------------

var notepad = new Notepad();
var webSearcher = new WebSearcher();

AITool[] tools =
[
    AIFunctionFactory.Create(webSearcher.SearchWeb),
    AIFunctionFactory.Create(notepad.SaveNote),
    AIFunctionFactory.Create(notepad.GetNotes),
];

// --- Build the agent ---------------------------------------------------------

IChatClient chatClient = new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic you must:
        1. Search the web for relevant information (perform 2-3 searches with varied queries).
        2. Save the key findings as notes using the note-taking tool.
        3. After gathering enough information, retrieve all your notes and write a concise
           summary with the most important points.
        Always cite your sources. Be thorough but concise.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

// --- Run the agent -----------------------------------------------------------

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    options: runOptions);

Console.WriteLine("═══════════════════════════════════════════════════════════════");
Console.WriteLine("  RESEARCH SUMMARY");
Console.WriteLine("═══════════════════════════════════════════════════════════════");
Console.WriteLine(response.Text);
Console.WriteLine("═══════════════════════════════════════════════════════════════");

if (notepad.Notes.Count > 0)
{
    Console.WriteLine($"\n({notepad.Notes.Count} note(s) collected during research)\n");
}

// =============================================================================
// Tool implementations
// =============================================================================

/// <summary>
/// Provides a simple in-memory notepad for the agent to store and retrieve findings.
/// </summary>
sealed class Notepad
{
    private readonly List<string> _notes = [];

    public IReadOnlyList<string> Notes => _notes;

    [Description("Save a research note. Use this to record key findings from web searches.")]
    public string SaveNote(
        [Description("The note content to save, including source attribution.")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved successfully. Total notes: {_notes.Count}";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        return string.Join("\n\n---\n\n", _notes.Select((n, i) => $"Note {i + 1}:\n{n}"));
    }
}

/// <summary>
/// Provides web search capabilities using the DuckDuckGo instant-answer API (no key required).
/// </summary>
sealed class WebSearcher : IDisposable
{
    private readonly HttpClient _httpClient = new()
    {
        DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information on a query. Returns a summary of search results.")]
    public async Task<string> SearchWeb(
        [Description("The search query string.")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🔍 Searching: {query}");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            var json = await _httpClient.GetFromJsonAsync<JsonElement>(url, cancellationToken);

            var results = new List<string>();

            // Abstract (instant answer)
            var abstractText = json.GetPropertyOrDefault("AbstractText");
            var abstractSource = json.GetPropertyOrDefault("AbstractSource");
            var abstractUrl = json.GetPropertyOrDefault("AbstractURL");

            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add($"**{abstractSource}** ({abstractUrl}):\n{abstractText}");
            }

            // Related topics
            if (json.TryGetProperty("RelatedTopics", out var topics) && topics.ValueKind == JsonValueKind.Array)
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    var text = topic.GetPropertyOrDefault("Text");
                    var firstUrl = topic.GetPropertyOrDefault("FirstURL");

                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.Add($"- {text} ({firstUrl})");
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No results found for '{query}'. Try a different search query.";
            }

            return $"Search results for '{query}':\n\n{string.Join("\n\n", results)}";
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            return $"Search failed for '{query}': {ex.Message}. Try a different query.";
        }
    }

    public void Dispose() => _httpClient.Dispose();
}

/// <summary>
/// Extension methods for safe JSON property access.
/// </summary>
static class JsonElementExtensions
{
    public static string GetPropertyOrDefault(this JsonElement element, string propertyName)
    {
        return element.TryGetProperty(propertyName, out var value) && value.ValueKind == JsonValueKind.String
            ? value.GetString() ?? string.Empty
            : string.Empty;
    }
}

